package com.example.shelflife;

import android.os.Bundle;
import android.widget.*;
import android.view.View;
import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.appcompat.app.AlertDialog;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
import java.time.*;
import java.util.*;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
public class ReportActivity extends ProtectedActivity {
 private List<Product> current=new ArrayList<>();private List<StockMovement> movements=new ArrayList<>();private String pendingCsv="";private StockRepository repo;private Button export;
 private final ActivityResultLauncher<String> createFile=registerForActivityResult(new ActivityResultContracts.CreateDocument("text/csv"),uri->{if(uri==null){export.setEnabled(true);return;}String contents=pendingCsv;Auth.IO.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new java.io.IOException("No output stream");out.write(("\uFEFF"+contents).getBytes(StandardCharsets.UTF_8));runOnUiThread(()->{export.setEnabled(true);Toast.makeText(this,"CSV file saved",Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->{export.setEnabled(true);Toast.makeText(this,"Export failed. Please retry.",Toast.LENGTH_LONG).show();});}});});
 @Override protected void onCreate(Bundle state){super.onCreate(state);if(isFinishing())return;setContentView(R.layout.activity_report);Screens.insets(this);repo=new StockRepository(this);if(state!=null)pendingCsv=state.getString("csv","");MaterialToolbar toolbar=findViewById(R.id.toolbar);toolbar.setTitle("Grocery reports");toolbar.setNavigationOnClickListener(v->finish());export=findViewById(R.id.btnExport);export.setOnClickListener(v->new MaterialAlertDialogBuilder(this).setTitle("Save a CSV report").setItems(new String[]{"Inventory batches","Stock movement history"},(d,which)->{pendingCsv=which==0?inventoryCsv():movementCsv();export.setEnabled(false);createFile.launch("ShelfLife-"+(which==0?"inventory":"movements")+"-"+LocalDate.now()+".csv");}).show());
  repo.dao.observeAll().observe(this,list->{current=list;render();});repo.dao.observeMovements().observe(this,list->{movements=list;render();});findViewById(R.id.btnReverse).setOnClickListener(v->chooseReversal());
 }
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("csv",pendingCsv);}
 Product product(long id){for(Product p:current)if(p.id==id)return p;return null;}
 boolean reversed(long id){for(StockMovement m:movements)if(m.reversalOf!=null&&m.reversalOf==id)return true;return false;}
 void render(){Set<String> sku=new HashSet<>();int expired=0,today=0,soon=0,unknown=0;StringBuilder attention=new StringBuilder(),history=new StringBuilder();Map<String,Double>waste=new LinkedHashMap<>();
  for(Product p:current)if(!p.archived){sku.add(p.sku);if(p.quantity>0){long days=Expiry.daysLeft(p);if("Expiry".equals(p.dateType)){if(days<0)expired++;else if(days==0)today++;else if(days<=7)soon++;}if(p.expiryDate==null)unknown++;if(days<=7||p.expiryDate==null)attention.append(p.name).append(" · ").append(p.stockReference).append(" · ").append(Rules.qty(p.quantity)).append(' ').append(p.unit).append("\n").append(p.dateType).append(": ").append(Expiry.date(p)).append(" · ").append(Expiry.label(p)).append("\n\n");}}
  for(StockMovement m:movements){Product p=product(m.batchId);if(p==null)continue;history.append('#').append(m.id).append(' ').append(m.reason).append(" · ").append(m.delta>0?"+":"").append(Rules.qty(m.delta)).append(' ').append(m.unit==null?p.unit:m.unit).append("\n").append(p.name).append(" · ").append(p.stockReference).append("\n").append(Instant.ofEpochMilli(m.time).atZone(ZoneId.systemDefault()).toLocalDateTime()).append(" · ").append(m.staffName).append("\n").append(Objects.toString(m.note,"")).append(reversed(m.id)?" [REVERSED]":"").append("\n\n");if(!reversed(m.id)&&("Expired".equals(m.reason)||"Damaged".equals(m.reason))){String key=p.name+" / "+p.sku+" ("+(m.unit==null?p.unit:m.unit)+")";waste.put(key,waste.getOrDefault(key,0.0)-m.delta);}}
  StringBuilder losses=new StringBuilder("Net stock removed due to expiry / damage:\n");if(waste.isEmpty())losses.append("None recorded.\n");for(Map.Entry<String,Double> e:waste.entrySet())losses.append(e.getKey()).append(": ").append(Rules.qty(Rules.rounded(e.getValue()))).append('\n');
  ((TextView)findViewById(R.id.tvGenerated)).setText("As of "+LocalDate.now().format(Expiry.DISPLAY)+" · "+ZoneId.systemDefault());((TextView)findViewById(R.id.tvTotal)).setText("Active grocery products: "+sku.size());((TextView)findViewById(R.id.tvExpired)).setText("Expired batches still on hand: "+expired);((TextView)findViewById(R.id.tv1)).setText("Batches expiring today: "+today);((TextView)findViewById(R.id.tv3)).setText("Batches expiring in 1–7 days: "+soon);((TextView)findViewById(R.id.tv7)).setText("Active batches with no printed date: "+unknown);((TextView)findViewById(R.id.tvAttention)).setText(attention.length()==0?"No active date alerts.":attention.toString());((TextView)findViewById(R.id.tvHistory)).setText(losses.toString());
  LinearLayout cards=findViewById(R.id.movementList);cards.removeAllViews();
  if(movements.isEmpty()){TextView empty=new TextView(this);empty.setText("No movements recorded yet. New stock changes will appear here. Legacy balances predate the ledger.");empty.setTextColor(0xff667468);empty.setPadding(12,24,12,24);cards.addView(empty);}
  for(StockMovement m:movements){Product p=product(m.batchId);if(p==null)continue;View card=getLayoutInflater().inflate(R.layout.item_movement,cards,false);((TextView)card.findViewById(R.id.movementReason)).setText(m.reason.toUpperCase(Locale.ROOT)+(reversed(m.id)?" · REVERSED":""));((TextView)card.findViewById(R.id.movementProduct)).setText(p.name);TextView amount=card.findViewById(R.id.movementAmount);amount.setText((m.delta>0?"+":"")+Rules.qty(m.delta)+" "+(m.unit==null?p.unit:m.unit));amount.setTextColor(m.delta>0?0xff166534:0xff8A5B09);((TextView)card.findViewById(R.id.movementMeta)).setText("Movement #"+m.id+" · Stock B"+m.batchId+"\n"+Instant.ofEpochMilli(m.time).atZone(ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("dd MMM yyyy · HH:mm"))+" · "+m.staffName);TextView note=card.findViewById(R.id.movementNote);note.setText(m.note);note.setVisibility(m.note==null||m.note.isEmpty()?View.GONE:View.VISIBLE);cards.addView(card);}

 }
 String inventoryCsv(){StringBuilder csv=new StringBuilder("Name,SKU,Barcode,BatchId,StockReference,SupplierLot,Category,Brand,Quantity,Unit,Location,DateLabel,PrintedDate,Status,Archived,Deleted,ProductId,PackSize,Variation,QuantityReceived,MeasurementValue,MeasurementUnit\r\n");for(Product p:current)csv.append(Csv.text(p.name)).append(',').append(Csv.text(p.sku)).append(',').append(Csv.text(p.barcode)).append(',').append(p.id).append(',').append(Csv.text(p.stockReference)).append(',').append(Csv.text(p.batchNo)).append(',').append(Csv.text(p.category)).append(',').append(Csv.text(p.brand)).append(',').append(Rules.qty(p.quantity)).append(',').append(Csv.text(p.unit)).append(',').append(Csv.text(p.location)).append(',').append(Csv.text(p.dateType)).append(',').append(p.expiryDate==null?"":p.expiry()).append(',').append(Csv.text(Expiry.label(p))).append(',').append(p.archived).append(',').append(p.deleted).append(',').append(p.productId).append(',').append(Csv.text(p.packSize)).append(',').append(Csv.text(p.variation)).append(',').append(Rules.qty(p.received)).append(',').append(Csv.text(p.measurementValue)).append(',').append(Csv.text(p.measurementUnit)).append("\r\n");return csv.toString();}
 String movementCsv(){StringBuilder csv=new StringBuilder("MovementId,BatchId,SKU,Name,Delta,Unit,Reason,Staff,TimestampUTC,Note,ReversalOf\r\n");for(StockMovement m:movements){Product p=product(m.batchId);if(p==null)continue;csv.append(m.id).append(',').append(m.batchId).append(',').append(Csv.text(p.sku)).append(',').append(Csv.text(p.name)).append(',').append(Rules.qty(m.delta)).append(',').append(Csv.text(m.unit==null?p.unit:m.unit)).append(',').append(Csv.text(m.reason)).append(',').append(Csv.text(m.staffName)).append(',').append(Instant.ofEpochMilli(m.time)).append(',').append(Csv.text(m.note)).append(',').append(m.reversalOf==null?"":m.reversalOf).append("\r\n");}return csv.toString();}
 void chooseReversal(){List<StockMovement>eligible=new ArrayList<>();for(StockMovement m:movements)if(!"Quantity correction".equals(m.reason)&&m.reversalOf==null&&!reversed(m.id))eligible.add(m);if(eligible.isEmpty()){Toast.makeText(this,"No movements to reverse",Toast.LENGTH_LONG).show();return;}String[] labels=new String[eligible.size()];for(int i=0;i<labels.length;i++){StockMovement m=eligible.get(i);Product p=product(m.batchId);labels[i]="#"+m.id+" "+m.reason+" · B"+m.batchId+" · "+Rules.qty(m.delta)+" "+(m.unit!=null?m.unit:p==null?"":p.unit);}new MaterialAlertDialogBuilder(this).setTitle("Correct a recorded movement").setItems(labels,(d,pos)->reverse(eligible.get(pos))).setNegativeButton("Cancel",null).show();}
 void reverse(StockMovement movement){View box=getLayoutInflater().inflate(R.layout.dialog_reversal,null);EditText note=box.findViewById(R.id.dialogInput);TextView error=box.findViewById(R.id.tvError);((TextView)box.findViewById(R.id.dialogHint)).setText("An inverse movement is added; the original stays in history. Restore archived products first.");AlertDialog d=new MaterialAlertDialogBuilder(this).setTitle("Reverse #"+movement.id+"?").setView(box).setPositiveButton("Reverse",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(!Screens.required(note))return;String reason=Screens.text(note);d.getButton(-1).setEnabled(false);d.getButton(-2).setEnabled(false);d.setCancelable(false);Auth.IO.execute(()->{try{if(Auth.session(this)!=repo.staffId)throw new IllegalArgumentException("Session ended");repo.reverse(movement.id,reason);runOnUiThread(d::dismiss);}catch(Exception e){runOnUiThread(()->{d.getButton(-1).setEnabled(true);d.getButton(-2).setEnabled(true);d.setCancelable(true);error.setText(Screens.error(e));});}});}));d.show();}
}
